create table agency_post_controls(tenant_id text not null,package_id text not null,state text not null default 'active' check(state in ('active','paused','terminated')),version bigint not null default 1,evidence_hash text not null,authority_note text not null,updated_by text not null,updated_at timestamptz not null default now(),primary key(tenant_id,package_id),foreign key(tenant_id,package_id) references agency_packages(tenant_id,id));
